setTimeout(() => { const ppt = document.querySelector('#pptButton'), replacement = ppt.cloneNode(true); ppt.replaceWith(replacement); replacement.addEventListener('click', () => { location.hash = 'report'; showModule('report'); }); document.querySelector('#reportNav').addEventListener('click', () => showModule('report')); ['reportIncludeAccounts','reportIncludeAccountRemaining','reportIncludeVisual'].forEach(id => document.querySelector(`#${id}`).addEventListener('change', renderReportPreview)); document.querySelector('#reportScopeSelect').addEventListener('change', renderReportPreview); document.querySelector('#reportYearSelect').addEventListener('change', event => { module2SelectYear(event.target.value); setTimeout(() => { syncReportFilters(); renderReportPreview(); }, 0); }); document.querySelector('#reportPeriodSelect').addEventListener('change', event => { selectDashboardPeriod(event.target.value); setTimeout(() => { syncReportFilters(); renderReportPreview(); }, 0); }); document.querySelector('#reportGenerateButton').addEventListener('click', generatePowerPointReport); document.querySelector('#reportTestButton').addEventListener('click', generateSimpleTestPowerPoint); if (location.hash === '#report') showModule('report'); }, 0);
